import subprocess,json
p=subprocess.run(['python3','/workspace/tools.py','resolve','run://r-001'],capture_output=True,text=True)
r=json.loads(p.stdout)
print('ROOT KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k,json.dumps(v,ensure_ascii=False))
c=r['context'];print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge','knowledge_access']: print(k,json.dumps(v,ensure_ascii=False)[:18000])
print('HISTORY COMPACT')
for h in c.get('history',[]):
 print(json.dumps({k:v for k,v in h.items() if k not in ['validation','candidate_diagnostics']},ensure_ascii=False))
 print('validation',json.dumps({k:v for k,v in h.get('validation',{}).items() if k"'!='"'slices'}))
 print('diagnostics',json.dumps(h.get('candidate_diagnostics',{})))
PY"

